#include <stdio.h>

int main(void) {
    const char *s = "34+2*";   /* (3+4)*2 */
    int st[64], top = 0;
    for (int i = 0; s[i]; i++) {
        char c = s[i];
        if (c >= '0' && c <= '9') { st[top++] = c - '0'; }
        else {
            int b = st[--top], a = st[--top], r = 0;
            if (c == '+') r = a + b;
            else if (c == '-') r = a - b;
            else if (c == '*') r = a * b;
            else r = a / b;
            st[top++] = r;
        }
    }
    printf("后缀表达式: %s\n", s);
    printf("求值结果: %d\n", st[--top]);
    return 0;
}
